 for(int op=0;op<14;op++){calls=0;requests=0;dispatch=0;leaves=new StringBuilder("[");actor=-1;int beforePool=hash(e.readMemory(toAddr(P),500*44)),beforeTrail=hash(e.readMemory(toAddr(H),trail.length));if(op==0||op==5)call(e,0x40e790,B+(op==0?0:256));else{actor=op==1||op==3||op==6||op==8||op==12?(oldCount==0?-1:0):op==2||op==4||op==10?oldLast:op==7||op==9?newFirst:op==11?newLast:(newLast>=0?newLast:oldLast);if(actor>=0&&(short)read(e,P+actor*44,2)!=-1000){if(op>=12){put(e,P+actor*44+18,2,0);put(e,P+actor*44+4,2,-1);}call(e,0x4028a0,P+actor*44);}}leaves.append(']');out.print("{\"kind\":"+kind+",\"scenario\":"+s+",\"op\":"+op+",\"n\":"+n+",\"capacity\":"+cap+",\"gate\":"+gate+",\"mp\":"+mp+",\"oldCount\":"+oldCount+",\"newCount\":"+newCount+",\"actor\":"+actor+",\"beforePool\":"+(beforePool&0xffffffffL)+",\"pool\":"+(hash(e.readMemory(toAddr(P),500*44))&0xffffffffL)+",\"beforeTrail\":"+(beforeTrail&0xffffffffL)+",\"trail\":"+(hash(e.readMemory(toAddr(H),trail.length))&0xffffffffL)+",\"header\":\""+hex(e.readMemory(toAddr(header),12))+"\",\"old\":\""+(oldCount==0?"":hex(e.readMemory(toAddr(P),44)))+"\",\"actorBytes\":\""+(actor<0?"":hex(e.readMemory(toAddr(P+actor*44),44)))+"\",\"calls\":"+calls+",\"requests\":"+requests+",\"dispatch\":"+dispatch+",\"leaves\":"+leaves+",\"projectX\":"+(short)read(e,0x4a6520,2)+",\"projectY\":"+(short)read(e,0x4a6530,2)+",\"byte32\":"+read(e,0x4a6522,1)+",\"payload36\":"+read(e,0x4a67fc,4)+",\"payload40\":"+read(e,0x4a6800,4)+",\"last\":"+read(e,0x4a6528,4)+",\"maximum\":"+read(e,0x4d18f3,1)+",\"tint\":"+read(e,0x4d18f2,1)+",\"suppression\":"+read(e,0x4d18fa,1)+",\"error\":"+read(e,0x4d18e2,1)+",\"soundGate\":"+read(e,0x4d18ee,1));for(int i=0;i<5;i++)out.print(",\"r"+i+"\":"+read(e,0x622cdc+i*4,4));out.println("}");}
